package com.bank.ledger.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "ledger_entries")
public class LedgerEntry {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long entryId;
    private String accountId;
    private String direction;      // DEBIT or CREDIT
    private BigDecimal amount;
    private BigDecimal balanceAfter;
    private LocalDateTime committedAt;

    public LedgerEntry() {}
    public LedgerEntry(String accountId, String direction, BigDecimal amount, BigDecimal balanceAfter) {
        this.accountId = accountId; this.direction = direction;
        this.amount = amount; this.balanceAfter = balanceAfter;
        this.committedAt = LocalDateTime.now();
    }
    public Long getEntryId() { return entryId; }
    public BigDecimal getBalanceAfter() { return balanceAfter; }
}
