package com.bank.ledger.service;

import com.bank.ledger.model.LedgerEntry;
import com.bank.ledger.repository.LedgerRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class LedgerService {
    private static final Logger log = LoggerFactory.getLogger(LedgerService.class);
    private final LedgerRepository repo;

    public LedgerService(LedgerRepository repo) { this.repo = repo; }

    // When this @Transactional method commits, PostgreSQL appends the WAL records
    // and fsyncs them BEFORE acknowledging success. If the server crashes right
    // after, crash recovery replays the WAL and the entries are NOT lost.
    @Transactional
    public void postTransfer(String fromId, BigDecimal fromBalanceAfter,
                             String toId, BigDecimal toBalanceAfter, BigDecimal amount) {
        repo.save(new LedgerEntry(fromId, "DEBIT", amount, fromBalanceAfter));
        repo.save(new LedgerEntry(toId, "CREDIT", amount, toBalanceAfter));
        log.info("Ledger transfer committed (WAL-durable): {} {}->{}", amount, fromId, toId);
    }
}
